 class memoized( object ):
    def __init__( self, function ):
       self.function = function
       self.cache = {}
    def __call__( self, *arguments ):
       try:
          return self.cache[ arguments ]
       except KeyError:
          value = self.function( *arguments )
          self.cache[ arguments ] = value
          return value

