             return (False, "Game has not completed")
         if(char == "x" or char == "X"):
             has_x = True
         if(char == "o" or char == "O"):
             has_o = True

     if has_o and has_x:
         return (False, "Draw")
     if has_o:
         return (True, "O won")
     return (True, "X won")

