 def is_higher(a, i, j, N, M):
     s = a[i][j]
     v, h = False, False
     for ii in xrange(N):
         if a[ii][j] > s:
             v = True
             break
     for jj in xrange(M):
         if a[i][jj] > s:
             h = True
             break
     return v and h

 def check(a, N, M):
     if N == 1 or M == 1:
         return True
     else:
         for i in xrange(N):
             for j in xrange(M):
                 h = is_higher(a, i, j, N, M)
                 if h:
                     return False
         return True

