(n):
     if n in square:
         return True
     if is_fair(n):
         root = int(math.sqrt(n))
         if root**2 != n:
             return False
         ss = is_fair(root)
         if ss: square.add(n)
         return ss
     return False

 def is_fair(n):
     if n in fair:
         return True
     if n in unfair:
         return False
     sn = str(n)
     l = len(sn)
     mid = math.ceil(n/2)
     if sn[0:mid] == sn[mid::-1]:
         fair.add(n)
         return True
     else:
         unfair.add(n)
         return False

