 def read_case(f):
     R1 = read_int(f)
     Q1 = read_arr(f, 4)
     R2 = read_int(f)
     Q2 = read_arr(f, 4)
     return (R1, Q1, R2, Q2)

 def write_case(f, i, res):
     f.write('Case #%d: '%i)
     f.write('%s'%res)
     f.write('\n')

 ################################################################################

 def solve_small(case):
     (R1, Q1, R2, Q2) = case
     s = set(Q1[R1-1]) & set(Q2[R2-1])
     if len(s) == 0:
         return 'Volunteer cheated!'
     if len(s) == 1:
         return s.pop()
     return 'Bad magician!'

 def solve_large(case):
     return solve_small(case)

